CREATE TYPE "ProjectStatus" AS ENUM ('PLANNED','IN_PROGRESS','ON_HOLD','COMPLETED','CANCELLED');
CREATE TYPE "ServiceHealth" AS ENUM ('OPERATIONAL','DEGRADED','OUTAGE','MAINTENANCE');
CREATE TYPE "AnnouncementSeverity" AS ENUM ('INFO','MAINTENANCE','INCIDENT');
CREATE TYPE "TicketCategory" AS ENUM ('SOFTWARE','HARDWARE','ACCESS','SOFTWARE_REQUEST','NETWORK','ACCOUNT','OTHER');
CREATE TYPE "TicketPriority" AS ENUM ('LOW','MEDIUM','HIGH','URGENT');
CREATE TYPE "TicketStatus" AS ENUM ('NEW','IN_PROGRESS','RESOLVED','CLOSED');
CREATE TABLE "Project" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "progress" INTEGER NOT NULL DEFAULT 0, "status" "ProjectStatus" NOT NULL DEFAULT 'PLANNED', "startDate" TIMESTAMP(3), "expectedEndDate" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "published" BOOLEAN NOT NULL DEFAULT false, "isActive" BOOLEAN NOT NULL DEFAULT true, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ItServiceStatus" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "health" "ServiceHealth" NOT NULL DEFAULT 'OPERATIONAL', "published" BOOLEAN NOT NULL DEFAULT false, "isActive" BOOLEAN NOT NULL DEFAULT true, "sortOrder" INTEGER NOT NULL DEFAULT 0, "lastUpdatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ItServiceStatus_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Announcement" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "severity" "AnnouncementSeverity" NOT NULL DEFAULT 'INFO', "publishAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMP(3), "pinned" BOOLEAN NOT NULL DEFAULT false, "published" BOOLEAN NOT NULL DEFAULT false, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Announcement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupportTicket" ("id" TEXT NOT NULL, "trackingCode" TEXT NOT NULL, "requesterName" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT, "category" "TicketCategory" NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "priority" "TicketPriority" NOT NULL DEFAULT 'MEDIUM', "status" "TicketStatus" NOT NULL DEFAULT 'NEW', "internalNotes" TEXT NOT NULL DEFAULT '', "resolvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupportTicket_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TicketAttachment" ("id" TEXT NOT NULL, "ticketId" TEXT NOT NULL, "originalName" TEXT NOT NULL, "storageName" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "size" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TicketAttachment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SupportTicket_trackingCode_key" ON "SupportTicket"("trackingCode"); CREATE UNIQUE INDEX "TicketAttachment_storageName_key" ON "TicketAttachment"("storageName");
CREATE INDEX "Project_published_isActive_status_sortOrder_idx" ON "Project"("published","isActive","status","sortOrder"); CREATE INDEX "ItServiceStatus_published_isActive_sortOrder_idx" ON "ItServiceStatus"("published","isActive","sortOrder"); CREATE INDEX "Announcement_published_isActive_publishAt_expiresAt_idx" ON "Announcement"("published","isActive","publishAt","expiresAt"); CREATE INDEX "SupportTicket_status_createdAt_idx" ON "SupportTicket"("status","createdAt"); CREATE INDEX "SupportTicket_email_trackingCode_idx" ON "SupportTicket"("email","trackingCode"); CREATE INDEX "TicketAttachment_ticketId_idx" ON "TicketAttachment"("ticketId");
ALTER TABLE "TicketAttachment" ADD CONSTRAINT "TicketAttachment_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "SupportTicket"("id") ON DELETE CASCADE ON UPDATE CASCADE;
